// ─── GEO → CANVAS PROJECTION ─────────────────────────────────
// Fit all warped station coords + boundary into canvas
let geoMinX=77.0, geoMaxX=77.6, geoMinY=28.35, geoMaxY=28.78;

function computeGeoBounds() {
  const allX = [...DELHI_DATA.s.map(s=>s.x), ...BOUNDARY.map(c=>c[0])];
  const allY = [...DELHI_DATA.s.map(s=>s.y), ...BOUNDARY.map(c=>c[1])];
  geoMinX = Math.min(...allX) - 0.01;
  geoMaxX = Math.max(...allX) + 0.01;
  geoMinY = Math.min(...allY) - 0.01;
  geoMaxY = Math.max(...allY) + 0.01;
}

function geoToCanvas(gx, gy) {
  const W = mapCanvas.width,  H = mapCanvas.height;
  const pad = 28;
  const scaleX = (W - pad*2) / (geoMaxX - geoMinX);
  const scaleY = (H - pad*2) / (geoMaxY - geoMinY);
  const scale  = Math.min(scaleX, scaleY);
  const offsetX = (W - scale*(geoMaxX-geoMinX)) / 2;
  const offsetY = (H - scale*(geoMaxY-geoMinY)) / 2;
  const cx = offsetX + (gx - geoMinX) * scale;
  const cy = H - offsetY - (gy - geoMinY) * scale;
  // Apply viewport pan + zoom centered on canvas
  const pivX = W/2, pivY = H/2;
  return {
    x: pivX + (cx - pivX) * state.viewScale + state.viewOffsetX,
    y: pivY + (cy - pivY) * state.viewScale + state.viewOffsetY,
  };
}

function canvasToGeo(px, py) {
  const W = mapCanvas.width, H = mapCanvas.height;
  const pad = 28;
  const scaleX = (W - pad*2) / (geoMaxX - geoMinX);
  const scaleY = (H - pad*2) / (geoMaxY - geoMinY);
  const scale  = Math.min(scaleX, scaleY);
  const offsetX = (W - scale*(geoMaxX-geoMinX)) / 2;
  const offsetY = (H - scale*(geoMaxY-geoMinY)) / 2;
  const pivX = W/2, pivY = H/2;
  const cx = (px - state.viewOffsetX - pivX) / state.viewScale + pivX;
  const cy = (py - state.viewOffsetY - pivY) / state.viewScale + pivY;
  const gx = (cx - offsetX) / scale + geoMinX;
  const gy = (H - cy - offsetY) / scale + geoMinY;
  return { gx, gy };
}

// ─── HEAT COLOR ───────────────────────────────────────────────
function heatColor(t, alpha=1) {
  const stops = HEAT_COLORS;
  let lo = stops[0], hi = stops[stops.length-1];
  for (let i=0; i<stops.length-1; i++) {
    if (t >= stops[i][0] && t <= stops[i+1][0]) { lo=stops[i]; hi=stops[i+1]; break; }
  }
  const f = lo[0]===hi[0] ? 0 : (t-lo[0])/(hi[0]-lo[0]);
  const r = Math.round(lo[1][0]+(hi[1][0]-lo[1][0])*f);
  const g = Math.round(lo[1][1]+(hi[1][1]-lo[1][1])*f);
  const b = Math.round(lo[1][2]+(hi[1][2]-lo[1][2])*f);
  return `rgba(${r},${g},${b},${alpha})`;
}

function stationTravelT(station) {
  return Math.min(1, (station.t||0) / MAX_TIME_MINUTES);
}

// ─── NEAREST STATION ─────────────────────────────────────────
function nearestStation(px, py, maxPx=HOVER_HIT_RADIUS_PX) {
  let best=null, bestD=maxPx*maxPx;
  for (const s of DELHI_DATA.s) {
    const c = geoToCanvas(s.x, s.y);
    const dx=c.x-px, dy=c.y-py, d2=dx*dx+dy*dy;
    if (d2 < bestD) { bestD=d2; best=s; }
  }
  return best;
}

// ─── BASEMAP TILES ────────────────────────────────────────────
function drawBasemap() {
  if (!state.basemapVisible) return;
  const zoom = Math.min(14, Math.max(9, Math.round(10 + Math.log2(state.viewScale))));
  const W = mapCanvas.width / devicePixelRatio;
  const H = mapCanvas.height / devicePixelRatio;
  function lon2tile(lon, z) { return Math.floor((lon + 180) / 360 * Math.pow(2, z)); }
  function lat2tile(lat, z) {
    return Math.floor((1 - Math.log(Math.tan(lat * Math.PI / 180) + 1 / Math.cos(lat * Math.PI / 180)) / Math.PI) / 2 * Math.pow(2, z));
  }
  const centerGeo = canvasToGeo(W / 2, H / 2);
  const centerTileX = lon2tile(centerGeo.gx, zoom);
  const centerTileY = lat2tile(centerGeo.gy, zoom);
  for (let dx = -4; dx <= 4; dx++) {
    for (let dy = -4; dy <= 4; dy++) {
      const tx = centerTileX + dx;
      const ty = centerTileY + dy;
      const key = `${zoom}_${tx}_${ty}`;
      if (!state.tileCache[key]) {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.src = TILE_URL.replace('{z}', zoom).replace('{x}', tx).replace('{y}', ty);
        img.onload = () => { state.dirty = true; requestDraw(); };
        state.tileCache[key] = img;
      }
      const img = state.tileCache[key];
      if (img.complete && img.naturalWidth > 0) {
        const tileLon     = tx / Math.pow(2, zoom) * 360 - 180;
        const tileLonR    = (tx + 1) / Math.pow(2, zoom) * 360 - 180;
        const tileLat     = Math.atan(Math.sinh(Math.PI * (1 - 2 * ty / Math.pow(2, zoom)))) * 180 / Math.PI;
        const tileLatB    = Math.atan(Math.sinh(Math.PI * (1 - 2 * (ty + 1) / Math.pow(2, zoom)))) * 180 / Math.PI;
        const pt1 = geoToCanvas(tileLon,  tileLat);
        const pt2 = geoToCanvas(tileLonR, tileLatB);
        ctx.globalAlpha = 0.38;
        ctx.drawImage(img, pt1.x, pt1.y, pt2.x - pt1.x, pt2.y - pt1.y);
        ctx.globalAlpha = 1;
      }
    }
  }
}

// ─── DRAW ─────────────────────────────────────────────────────
function draw() {
  const W = mapCanvas.width, H = mapCanvas.height;
  ctx.clearRect(0,0,W,H);

  // Background
  ctx.fillStyle = '#ddd8ce';
  ctx.fillRect(0,0,W,H);

  drawBasemap();

  // ── 1. Boundary fill ──────────────────────────────────────
  ctx.save();
  ctx.beginPath();
  BOUNDARY.forEach((c,i) => {
    const pt = geoToCanvas(c[0], c[1]);
    i===0 ? ctx.moveTo(pt.x,pt.y) : ctx.lineTo(pt.x,pt.y);
  });
  ctx.closePath();
  ctx.fillStyle = '#e8e2d4';
  ctx.fill();

  // subtle road texture (fine grid inside boundary)
  ctx.clip();
  ctx.strokeStyle = 'rgba(195,190,180,0.45)';
  ctx.lineWidth = 0.5;
  const gridStep = 22;
  for(let x=0; x<W; x+=gridStep) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
  for(let y=0; y<H; y+=gridStep) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
  ctx.restore();

  // ── 2. Heatmap blobs ──────────────────────────────────────
  if (state.showHeatmap) {
    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    const R = Math.max(35, W * 0.07);
    for (const s of DELHI_DATA.s) {
      const t  = stationTravelT(s);
      const pt = geoToCanvas(s.x, s.y);
      const alpha = 0.55 * (1 - t*0.3);
      const grad = ctx.createRadialGradient(pt.x,pt.y,0, pt.x,pt.y,R);
      grad.addColorStop(0, heatColor(t, alpha));
      grad.addColorStop(0.6, heatColor(t, alpha*0.4));
      grad.addColorStop(1, heatColor(t, 0));
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(pt.x,pt.y,R,0,Math.PI*2);
      ctx.fill();
    }
    ctx.restore();
  }

  // ── 3. Boundary outline ───────────────────────────────────
  ctx.save();
  ctx.beginPath();
  BOUNDARY.forEach((c,i) => {
    const pt = geoToCanvas(c[0],c[1]);
    i===0 ? ctx.moveTo(pt.x,pt.y) : ctx.lineTo(pt.x,pt.y);
  });
  ctx.closePath();
  ctx.strokeStyle = '#c47a30';
  ctx.lineWidth = state.viewScale < 1.5 ? 2 : 2.5;
  ctx.stroke();
  ctx.restore();

  // ── 4. 60-min reach outline ───────────────────────────────
  if (state.showOutline) {
    const within60 = DELHI_DATA.s.filter(s => s.t <= 60);
    if (within60.length > 2) {
      ctx.save();
      ctx.setLineDash([6,4]);
      ctx.strokeStyle = '#f15a24';
      ctx.lineWidth = 2;
      within60.forEach((s,i) => {
        const pt = geoToCanvas(s.x,s.y);
        i===0 ? ctx.moveTo(pt.x,pt.y) : ctx.lineTo(pt.x,pt.y);
      });
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
  }

  // ── 5. Metro route lines (white underline + colored) ──────
  for (const route of DELHI_DATA.r) {
    if (!route.p || route.p.length < 2) continue;
    const col = LINE_COLORS[route.c] || '#888';

    // White casing
    ctx.beginPath();
    route.p.forEach((c,i) => {
      const pt = geoToCanvas(c[0],c[1]);
      i===0 ? ctx.moveTo(pt.x,pt.y) : ctx.lineTo(pt.x,pt.y);
    });
    ctx.strokeStyle = 'rgba(255,255,255,0.75)';
    ctx.lineWidth = (state.viewScale < 2 ? 3.5 : 5) * state.viewScale;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();

    // Colored line
    ctx.beginPath();
    route.p.forEach((c,i) => {
      const pt = geoToCanvas(c[0],c[1]);
      i===0 ? ctx.moveTo(pt.x,pt.y) : ctx.lineTo(pt.x,pt.y);
    });
    ctx.strokeStyle = col;
    ctx.lineWidth = (state.viewScale < 2 ? 2 : 3) * state.viewScale;
    ctx.stroke();
  }

  // ── 6. Station dots ───────────────────────────────────────
  const dotR = Math.max(2.5, 3.5 * state.viewScale);
  for (const s of DELHI_DATA.s) {
    const pt = geoToCanvas(s.x, s.y);
    const t  = stationTravelT(s);
    const isOrigin = s.i === state.originId;
    const isHover  = s.i === state.hoverStationId;
    const isPinned = s.i === state.pinnedId;

    ctx.beginPath();
    ctx.arc(pt.x, pt.y, isOrigin ? dotR*1.6 : isHover ? dotR*1.3 : dotR, 0, Math.PI*2);
    ctx.fillStyle = isOrigin ? '#f15a24' : 'white';
    ctx.fill();
    ctx.strokeStyle = isOrigin ? 'white' : (LINE_COLORS[getStationLineColor(s)] || '#888');
    ctx.lineWidth = isOrigin ? 2 : 1;
    ctx.stroke();
  }

  // ── 7. Origin pulse rings ──────────────────────────────────
  const originS = DELHI_DATA.s.find(s=>s.i===state.originId);
  if (originS) {
    const opt = geoToCanvas(originS.x, originS.y);
    const pulse = (Date.now() % 2400) / 2400;
    const pR = dotR*1.6 + pulse*dotR*4;
    ctx.beginPath();
    ctx.arc(opt.x,opt.y,pR,0,Math.PI*2);
    ctx.strokeStyle = `rgba(241,90,36,${0.6*(1-pulse)})`;
    ctx.lineWidth = 2;
    ctx.stroke();
    // inner glow
    ctx.beginPath();
    ctx.arc(opt.x,opt.y,dotR*2.8,0,Math.PI*2);
    ctx.strokeStyle = `rgba(241,90,36,${0.25})`;
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  // ── 8. Hover tooltip ──────────────────────────────────────
  if (state.probeStation && !state.isMobile) {
    const s   = state.probeStation;
    const pt  = geoToCanvas(s.x, s.y);
    const t   = s.t;
    const label = t <= 0.5 ? 'Origin' : `${Math.round(t)} min away`;
    const text1 = s.n;
    const text2 = label;
    const pad2 = 9, lineH = 17;
    const w  = Math.max(ctx.measureText(text1).width, ctx.measureText(text2).width) + pad2*2;
    const h  = lineH*2 + pad2;
    const tx = Math.max(4, Math.min(W-w-4, pt.x - w/2));
    const ty = pt.y - h - dotR*2 - 6;

    ctx.save();
    ctx.shadowColor='rgba(0,0,0,0.18)'; ctx.shadowBlur=10;
    ctx.fillStyle='rgba(26,26,26,0.92)';
    roundRect(ctx, tx, ty, w, h, 7);
    ctx.fill();
    ctx.restore();

    ctx.font = `600 13px Inter, sans-serif`;
    ctx.fillStyle = 'white';
    ctx.textAlign = 'center';
    ctx.fillText(text1, tx+w/2, ty+pad2+11);
    ctx.font = `400 11.5px Inter, sans-serif`;
    ctx.fillStyle = t<=0.5 ? '#f15a24' : heatColor(Math.min(1,t/MAX_TIME_MINUTES), 1).replace('rgba','rgb').replace(/,[\d.]+\)$/,')');
    ctx.fillText(text2, tx+w/2, ty+pad2+lineH+10);
    ctx.textAlign = 'left';
  }

  state.dirty = false;
}

function roundRect(ctx, x,y,w,h,r) {
  ctx.beginPath();
  ctx.moveTo(x+r,y);
  ctx.lineTo(x+w-r,y); ctx.arcTo(x+w,y,x+w,y+r,r);
  ctx.lineTo(x+w,y+h-r); ctx.arcTo(x+w,y+h,x+w-r,y+h,r);
  ctx.lineTo(x+r,y+h); ctx.arcTo(x,y+h,x,y+h-r,r);
  ctx.lineTo(x,y+r); ctx.arcTo(x,y,x+r,y,r);
  ctx.closePath();
}

// ─── STATION LINE COLOR LOOKUP ────────────────────────────────
function getStationLineColor(station) {
  // Approximate line color from station id prefix pattern
  const id = station.i;
  const n  = parseInt(id.split('-')[1]);
  if (n>=1&&n<=21) return 'red';
  if (n>=22&&n<=35) return 'green';
  if (n>=36&&n<=71) return 'yellow';
  if (n>=72&&n<=121) return 'blue';
  if (n>=122&&n<=147) return 'violet';
  if (n>=148&&n<=153) return 'rapid';
  if (n>=154&&n<=157) return 'orange';
  if (n>=158&&n<=160) return 'violet';
  if (n>=161&&n<=167) return 'magenta';
  if (n>=168&&n<=172) return 'rapid';
  if (n>=173&&n<=218) return 'pink';
  if (n>=500) return 'aqua';
  return 'gray';
}

// ─── ANIMATION LOOP ───────────────────────────────────────────
let animFrame = null;
function requestDraw() {
  if (animFrame) return;
  animFrame = requestAnimationFrame(() => {
    animFrame = null;
    draw();
    // keep pulsing origin ring
    requestDraw();
  });
}

// ─── RESIZE ───────────────────────────────────────────────────
function resize() {
  const wrap = document.getElementById('mapWrap');
  mapCanvas.width  = wrap.offsetWidth  * devicePixelRatio;
  mapCanvas.height = wrap.offsetHeight * devicePixelRatio;
  mapCanvas.style.width  = wrap.offsetWidth  + 'px';
  mapCanvas.style.height = wrap.offsetHeight + 'px';
  ctx.scale(devicePixelRatio, devicePixelRatio);
  state.dirty = true;
  requestDraw();
}
window.addEventListener('resize', resize);

// ─── ZOOM ─────────────────────────────────────────────────────
function setZoom(factor) {
  state.viewScale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, state.viewScale * factor));
  state.dirty = true;
  requestDraw();
}

// ─── MOUSE / TOUCH EVENTS ─────────────────────────────────────
mapCanvas.addEventListener('mousemove', e => {
  const r  = mapCanvas.getBoundingClientRect();
  const px = e.clientX - r.left;
  const py = e.clientY - r.top;

  if (state.dragging && state.lastPointer) {
    state.viewOffsetX += (e.clientX - state.lastPointer.x);
    state.viewOffsetY += (e.clientY - state.lastPointer.y);
    state.lastPointer = { x: e.clientX, y: e.clientY };
    state.dirty = true;
    requestDraw();
    return;
  }

  const s = nearestStation(px, py, HOVER_HIT_RADIUS_PX * 2.5);
  if (s && s.i !== state.hoverStationId) {
    state.hoverStationId = s.i;
    state.probeStation   = s;
    state.dirty = true;
    requestDraw();
    updateMobileStatus(s);
  } else if (!s && state.hoverStationId) {
    state.hoverStationId = null;
    state.probeStation   = null;
    state.dirty = true;
    requestDraw();
  }
});

mapCanvas.addEventListener('mousedown', e => {
  state.dragging   = true;
  state.lastPointer= { x: e.clientX, y: e.clientY };
  mapCanvas.style.cursor = 'grabbing';
});

let dragMoved = false;

mapCanvas.addEventListener('mousedown', e => {
  state.dragging = true;
  dragMoved = false;

  state.lastPointer = {
    x: e.clientX,
    y: e.clientY
  };

  mapCanvas.style.cursor = 'grabbing';
});

mapCanvas.addEventListener('mousemove', e => {

  if (state.dragging && state.lastPointer) {

    const dx = e.clientX - state.lastPointer.x;
    const dy = e.clientY - state.lastPointer.y;

    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
      dragMoved = true;
    }

    state.viewOffsetX += dx;
    state.viewOffsetY += dy;

    state.lastPointer = {
      x: e.clientX,
      y: e.clientY
    };

    state.dirty = true;
    requestDraw();
    return;
  }

});

mapCanvas.addEventListener('mouseup', e => {

  state.dragging = false;
  state.lastPointer = null;

  mapCanvas.style.cursor = 'crosshair';

  // CLICK = change origin
  if (!dragMoved) {

    const r = mapCanvas.getBoundingClientRect();

    const s = nearestStation(
      e.clientX - r.left,
      e.clientY - r.top,
      PIN_HIT_RADIUS_PX
    );

    if (s) {
      setOrigin(s);
    }
  }
});

mapCanvas.addEventListener('mouseleave', () => {
  state.dragging=false; state.lastPointer=null;
  mapCanvas.style.cursor='crosshair';
});

mapCanvas.addEventListener('wheel', e => {
  e.preventDefault();
  const factor = e.deltaY < 0 ? ZOOM_STEP : 1/ZOOM_STEP;
  setZoom(factor);
}, { passive: false });

// Touch events for mobile
let lastTouchDist = null;
mapCanvas.addEventListener('touchstart', e => {
  e.preventDefault();
  if (e.touches.length === 1) {
    state.lastPointer = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    state.dragging = true;
  }
  if (e.touches.length === 2) {
    lastTouchDist = Math.hypot(
      e.touches[0].clientX - e.touches[1].clientX,
      e.touches[0].clientY - e.touches[1].clientY);
    state.dragging = false;
  }
}, { passive: false });

mapCanvas.addEventListener('touchmove', e => {
  e.preventDefault();
  if (e.touches.length === 2 && lastTouchDist) {
    const d = Math.hypot(e.touches[0].clientX-e.touches[1].clientX, e.touches[0].clientY-e.touches[1].clientY);
    const factor = d / lastTouchDist;
    setZoom(factor);
    lastTouchDist = d;
  } else if (e.touches.length === 1 && state.dragging && state.lastPointer) {
    state.viewOffsetX += e.touches[0].clientX - state.lastPointer.x;
    state.viewOffsetY += e.touches[0].clientY - state.lastPointer.y;
    state.lastPointer  = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    state.dirty = true;
    requestDraw();
  }
}, { passive: false });

mapCanvas.addEventListener('touchend', e => {
  lastTouchDist = null;
  state.dragging = false;
  // tap to set origin
  if (e.changedTouches.length === 1 && e.touches.length === 0) {
    const t = e.changedTouches[0];
    const r = mapCanvas.getBoundingClientRect();
    const s = nearestStation(t.clientX-r.left, t.clientY-r.top, PIN_HIT_RADIUS_PX*1.5);
    if (s) setOrigin(s);
  }
});

// ─── ORIGIN ───────────────────────────────────────────────────
function setOrigin(station) {
  state.originId = station.i;
  updateOriginUI(station);
  updateReachUI();
  hidePinHint();
  state.dirty = true;
  requestDraw();
  syncUrl();
}

function updateOriginUI(station) {
  const label = `Pinned near ${station.n}`;
  if (originLabel)      originLabel.textContent = label;
  if (mobileOriginTitle) mobileOriginTitle.textContent = label;
}

function updateMobileStatus(station) {
  if (!station) return;
  const t = station.t;
  const text = t<=0.5 ? 'This is your origin.' : `${Math.round(t)} min away from origin`;
  if (mobileStatusText) mobileStatusText.textContent = text;
  if (mobileTravelCallout) {
    mobileTravelCallout.hidden = t<=0.5;
    if (mobileTravelTime) mobileTravelTime.textContent = Math.round(t)+'m';
  }
  // Desktop callout
  if (travelCallout) {
    travelCallout.hidden = t<=0.5;
    if (travelTimeBig) travelTimeBig.textContent = Math.round(t)+' min';
    if (travelTimeSub) travelTimeSub.textContent = `from ${DELHI_DATA.s.find(s=>s.i===state.originId)?.n||'origin'}`;
  }
}

function clearOrigin() {
  state.originId = DEFAULT_ORIGIN_ID;
  const rc = DELHI_DATA.s.find(s=>s.i===DEFAULT_ORIGIN_ID);
  if (rc) updateOriginUI(rc);
  updateReachUI();
  if (travelCallout) travelCallout.hidden = true;
  if (mobileTravelCallout) mobileTravelCallout.hidden = true;
  showPinHint();
  state.dirty=true;
  requestDraw();
  syncUrl();
}

// ─── REACH UI ────────────────────────────────────────────────
function updateReachUI() {
  const within60 = DELHI_DATA.s.filter(s=>s.t<=60).length;
  const total    = DELHI_DATA.s.length;
  const pct      = Math.round(within60/total*100);
  const fillW    = pct+'%';
  if (reachValue)     reachValue.textContent = within60;
  if (reachPct)       reachPct.textContent   = pct+'% of network';
  if (reachBarFill)   reachBarFill.style.width = fillW;
  if (mobileReachValue) mobileReachValue.textContent = `${within60} / ${total}`;
  if (mobileReachBarFill) mobileReachBarFill.style.width = fillW;
}

// ─── PIN HINT ─────────────────────────────────────────────────
function showPinHint() { if(pinHint) pinHint.style.opacity='1'; }
function hidePinHint() { if(pinHint) pinHint.style.opacity='0'; }

// ─── STATION SEARCH ───────────────────────────────────────────
function searchStations(query) {
  if (!query.trim()) return [];
  const q = query.toLowerCase();
  return DELHI_DATA.s
    .filter(s => s.n.toLowerCase().includes(q))
    .slice(0, 6);
}

function renderSearchResults(results, container, meta) {
  if (!container) return;
  container.innerHTML = '';
  if (!results.length) {
    if (meta) meta.textContent = 'No stations found. Try a different name.';
    return;
  }
  if (meta) meta.textContent = '';
  results.forEach(s => {
    const item = document.createElement('div');
    item.className = 'search-result-item';
    item.innerHTML = `${s.n} <span class="search-result-time">${Math.round(s.t)}m</span>`;
    item.addEventListener('click', () => {
      setOrigin(s);
      panToStation(s);
      container.innerHTML = '';
      if (meta) meta.textContent = `Origin set to ${s.n}`;
    });
    container.appendChild(item);
  });
}

function panToStation(station) {
  // Center viewport on this station
  const W = mapCanvas.width/devicePixelRatio;
  const H = mapCanvas.height/devicePixelRatio;
  const pt = geoToCanvas(station.x, station.y);
  state.viewOffsetX += (W/2 - pt.x);
  state.viewOffsetY += (H/2 - pt.y);
  state.dirty=true;
  requestDraw();
}

// ─── SHARE ────────────────────────────────────────────────────
function getShareUrl() {
  const url = new URL(location.href);
  url.searchParams.set('origin', state.originId);
  return url.toString();
}

function syncUrl() {
  try {
    const url = new URL(location.href);
    url.searchParams.set('origin', state.originId);
    history.replaceState(null, '', url.toString());
  } catch(e){}
}

function restoreFromUrl() {
  const params = new URLSearchParams(location.search);
  const originId = params.get('origin');
  if (originId) {
    const s = DELHI_DATA.s.find(s=>s.i===originId);
    if (s) { state.originId=s.i; updateOriginUI(s); hidePinHint(); }
  }
}

async function downloadImage() {
  const link = document.createElement('a');
  link.download = 'delhi-metro-cartogram.png';
  link.href = mapCanvas.toDataURL('image/png');
  link.click();
}

// ─── EVENT WIRING ─────────────────────────────────────────────
function wireEvents() {
  // Zoom buttons
  [zoomInButton, zoomInFloat].forEach(btn => btn?.addEventListener('click', ()=>setZoom(ZOOM_STEP)));
  [zoomOutButton, zoomOutFloat].forEach(btn => btn?.addEventListener('click', ()=>setZoom(1/ZOOM_STEP)));

  // Fullscreen
  fullscreenButton?.addEventListener('click', async () => {
    try {
      if (document.fullscreenElement) await document.exitFullscreen();
      else await panelCard.requestFullscreen();
    } catch(e){}
  });

  // Toggles
  function syncToggle(a, b, key) {
    a?.addEventListener('change', ()=>{ state[key]=a.checked; if(b)b.checked=a.checked; state.dirty=true; requestDraw(); });
    b?.addEventListener('change', ()=>{ state[key]=b.checked; if(a)a.checked=b.checked; state.dirty=true; requestDraw(); });
  }
  syncToggle(warpToggle,    mobileWarpToggle,    'showWarp');
  syncToggle(heatmapToggle, mobileHeatmapToggle, 'showHeatmap');
  syncToggle(outlineToggle, mobileOutlineToggle, 'showOutline');

  // Basemap toggle
  const basemapToggle       = document.getElementById('basemapToggle');
  const mobileBasemapToggle = document.getElementById('mobileBasemapToggle');
  syncToggle(basemapToggle, mobileBasemapToggle, 'basemapVisible');

  // Share panel
  if (shareButton && sharePanel) {
    shareButton.addEventListener('click', e => {
      e.stopPropagation();
      sharePanel.hidden = !sharePanel.hidden;
    });
    document.addEventListener('click', e => {
      if (!sharePanel.contains(e.target) && !shareButton?.contains(e.target))
        sharePanel.hidden = true;
    });
  }
  copyLinkAction?.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(getShareUrl());
      const orig = copyLinkAction.textContent;
      copyLinkAction.textContent = '✓ Link copied!';
      setTimeout(() => { copyLinkAction.textContent = orig; }, 2000);
    } catch(e) {
      // fallback: select a temp input
      const inp = document.createElement('input');
      inp.value = getShareUrl();
      document.body.appendChild(inp);
      inp.select();
      document.execCommand('copy');
      document.body.removeChild(inp);
      copyLinkAction.textContent = '✓ Copied!';
      setTimeout(() => { copyLinkAction.textContent = 'Copy link'; }, 2000);
    }
    if(sharePanel) sharePanel.hidden=true;
  });
  downloadImageAction?.addEventListener('click', () => {
    downloadImage();
    if(sharePanel) sharePanel.hidden=true;
  });

  // Mobile share
  mobileShareButton?.addEventListener('click', async () => {
    if (navigator.share) {
      try { await navigator.share({ title: document.title, url: getShareUrl() }); }
      catch(e){}
    } else {
      try { await navigator.clipboard.writeText(getShareUrl()); }
      catch(e){}
    }
  });

  // Clear
  mobileClearButton?.addEventListener('click', clearOrigin);

  // Mobile sheet toggle
  mobileSheetToggle?.addEventListener('click', () => {
    state.drawerOpen = !state.drawerOpen;
    mobileSheet?.classList.toggle('collapsed', !state.drawerOpen);
  });

  // Mobile locate
  [mobileLocateButton, mobileInstructionsLocateButton].forEach(btn => {
    btn?.addEventListener('click', () => {
      navigator.geolocation?.getCurrentPosition(pos => {
        // Find nearest station to user location
        const { latitude: lat, longitude: lon } = pos.coords;
        let best=null, bestD=Infinity;
        DELHI_DATA.s.forEach(s => {
          const d=Math.hypot(s.x-lon, s.y-lat);
          if(d<bestD){bestD=d;best=s;}
        });
        if(best) { setOrigin(best); panToStation(best); }
        if(mobileMapInstructions) mobileMapInstructions.hidden=true;
        if(mobileHelpBubble) mobileHelpBubble.hidden=false;
      });
    });
  });

  // Mobile help bubble
  mobileMapInstructions?.addEventListener('click', e => {
    if (!e.target.closest('#mobileInstructionsLocateButton')) {
      if(mobileMapInstructions) mobileMapInstructions.hidden=true;
      if(mobileHelpBubble) mobileHelpBubble.hidden=false;
    }
  });
  mobileHelpBubble?.addEventListener('click', () => {
    if(mobileMapInstructions) mobileMapInstructions.hidden=false;
    if(mobileHelpBubble) mobileHelpBubble.hidden=true;
  });

  // Search
  function setupSearch(form, input, meta, results) {
    form?.addEventListener('submit', e => {
      e.preventDefault();
      const r = searchStations(input?.value||'');
      renderSearchResults(r, results, meta);
    });
    input?.addEventListener('input', () => {
      if (!input.value.trim()) { if(results) results.innerHTML=''; return; }
      const r = searchStations(input.value);
      renderSearchResults(r, results, meta);
    });
  }
  setupSearch(searchForm, addressInput, searchMeta, searchResults);
  setupSearch(mobileSearchForm, mobileAddressInput, mobileSearchMeta, mobileSearchResults);

  // Keyboard shortcuts
  document.addEventListener('keydown', e => {
    if (e.key==='+' || e.key==='=') setZoom(ZOOM_STEP);
    if (e.key==='-') setZoom(1/ZOOM_STEP);
    if (e.key==='Escape') { if(sharePanel) sharePanel.hidden=true; }
    if (e.key==='0') { state.viewScale=1; state.viewOffsetX=0; state.viewOffsetY=0; state.dirty=true; requestDraw(); }
  });

  // Responsive
  window.addEventListener('resize', () => {
    state.isMobile = window.innerWidth < 641;
  });
}

// ─── INIT ─────────────────────────────────────────────────────
function init() {
  computeGeoBounds();
  resize();
  restoreFromUrl();
  updateReachUI();

  const originStation = DELHI_DATA.s.find(s=>s.i===state.originId);
  if (originStation) updateOriginUI(originStation);

  wireEvents();

  // Hide loader text
  if (statusText) statusText.style.display = 'none';

  // Mobile sheet starts collapsed
  mobileSheet?.classList.add('collapsed');

  requestDraw();
}

init();
